/**
 * Must Drop Jackpot Widget
 * Image-based draggable widget with opt-in/opt-out and minimized states.
 * No external dependencies.
 */
(function () {
  "use strict";

  var IMG_OPTIN  = "data:image/png;base64,";
  var IMG_OPTOUT = "data:image/png;base64,";
  var IMG_BAR    = "data:image/png;base64,";

  var CHIP_W = 152, CHIP_H = 148;
  var BAR_W  = 181, BAR_H  = 46;

  var DEFAULTS = {
    name: "Must Drop",
    amount: 18915872.81,
    currency: "EUR",
    currencySymbol: "\u20AC",
    incrementRate: 1.23,
    incrementInterval: 2000,
    position: "top-left",
    containerId: null,
    draggable: true,
    onOptIn: null,
    onOptOut: null,
    onTerms: null
  };

  var STORAGE_KEY = "jackpot_mustdrop_optin";
  var P = "jw-md-";

  function injectStyles() {
    if (document.getElementById(P + "styles")) return;
    var css = [
      "." + P + "widget { z-index:999999; user-select:none; -webkit-user-select:none; font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif; }",
      "." + P + "widget." + P + "fixed { position:fixed; }",
      "." + P + "widget." + P + "contained { position:absolute; }",
      "." + P + "widget." + P + "pos-top-left     { top:10px; left:10px; }",
      "." + P + "widget." + P + "pos-top-right    { top:10px; right:10px; }",
      "." + P + "widget." + P + "pos-top-center   { top:10px; left:50%; transform:translateX(-50%); }",
      "." + P + "widget." + P + "pos-bottom-left  { bottom:60px; left:10px; }",
      "." + P + "widget." + P + "pos-bottom-right { bottom:60px; right:10px; }",

      /* chip */
      "." + P + "chip { position:relative; width:" + CHIP_W + "px; height:" + CHIP_H + "px; cursor:grab; }",
      "." + P + "chip." + P + "dragging { cursor:grabbing; }",
      "." + P + "chip-img { display:block; width:" + CHIP_W + "px; height:" + CHIP_H + "px; pointer-events:none; }",
      "." + P + "chip-btn { position:absolute; bottom:0; left:15%; width:70%; height:20%; cursor:pointer; background:transparent; border:none; z-index:5; }",

      /* chip top hit area — covers the top circular area of the image where the visual element is */
      "." + P + "chip-top { position:absolute; top:0; left:25%; width:50%; height:22%; cursor:pointer; z-index:6; border-radius:50% 50% 0 0; }",

      /* bar */
      "." + P + "bar { display:none; position:relative; width:" + BAR_W + "px; height:" + BAR_H + "px; cursor:grab; }",
      "." + P + "bar." + P + "dragging { cursor:grabbing; }",
      "." + P + "bar-img { display:block; width:" + BAR_W + "px; height:" + BAR_H + "px; pointer-events:none; }",

      /* bar hamburger */
      "." + P + "bar-menu { position:absolute; top:0; right:0; width:" + BAR_H + "px; height:" + BAR_H + "px; cursor:pointer; z-index:5; }",

      /* popup menu — position set dynamically via JS */
      "." + P + "popup { display:none; position:absolute; right:0; background:#1a0a35; border:1.5px solid rgba(184,134,11,0.5); border-radius:10px; padding:6px; z-index:10; box-shadow:0 4px 20px rgba(0,0,0,0.6); min-width:44px; }",
      "." + P + "popup." + P + "open { display:flex; flex-direction:column; gap:4px; }",

      /* menu item */
      "." + P + "mi { display:flex; align-items:center; gap:8px; padding:0 10px; margin:0; border:none; background:transparent; color:#ddd; font-size:12px; font-weight:600; cursor:pointer; border-radius:8px; white-space:nowrap; min-height:44px; min-width:44px; transition:background 0.15s; }",
      "." + P + "mi:hover { background:rgba(255,255,255,0.08); }",
      "." + P + "mi:active { background:rgba(255,255,255,0.14); }",

      "." + P + "mi-icon { width:20px; height:20px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }",
      "." + P + "mi-icon svg { width:18px; height:18px; }",

      "." + P + "mi-close svg { stroke:#ff6b6b; }",
      "." + P + "mi-min svg { stroke:#daa520; }",
      "." + P + "mi-terms svg { stroke:#8cb4ff; }",

      /* T&C modal overlay */
      "." + P + "overlay { display:none; position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.7); z-index:1000000; align-items:center; justify-content:center; padding:20px; }",
      "." + P + "overlay." + P + "open { display:flex; }",
      "." + P + "modal { background:#1a0a35; border:1.5px solid rgba(184,134,11,0.5); border-radius:14px; width:100%; max-width:360px; max-height:80vh; display:flex; flex-direction:column; overflow:hidden; }",
      "." + P + "modal-header { display:flex; align-items:center; justify-content:space-between; padding:14px 16px; border-bottom:1px solid rgba(184,134,11,0.25); flex-shrink:0; }",
      "." + P + "modal-title { font-size:14px; font-weight:700; color:#daa520; letter-spacing:0.5px; }",
      "." + P + "modal-x { width:36px; height:36px; display:flex; align-items:center; justify-content:center; border:none; background:transparent; cursor:pointer; border-radius:8px; transition:background 0.15s; }",
      "." + P + "modal-x:hover { background:rgba(255,255,255,0.08); }",
      "." + P + "modal-x svg { width:18px; height:18px; stroke:#ff6b6b; }",
      "." + P + "modal-body { padding:16px; overflow-y:auto; -webkit-overflow-scrolling:touch; flex:1; }",
      "." + P + "modal-body p { font-size:12px; line-height:1.7; color:#bbb; margin-bottom:12px; }",
      "." + P + "modal-body p:last-child { margin-bottom:0; }",
      "." + P + "modal-body strong { color:#ddd; }"
    ];

    var style = document.createElement("style");
    style.id = P + "styles";
    style.textContent = css.join("\n");
    document.head.appendChild(style);
  }

  var SVG_MINIMIZE = '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round"><line x1="5" y1="12" x2="19" y2="12"/></svg>';
  var SVG_EXPAND   = '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round"><line x1="5" y1="12" x2="19" y2="12"/><line x1="12" y1="5" x2="12" y2="19"/></svg>';
  var SVG_TERMS    = '<svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="8" y1="13" x2="16" y2="13"/><line x1="8" y1="17" x2="16" y2="17"/></svg>';
  var SVG_CLOSE    = '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round"><line x1="6" y1="6" x2="18" y2="18"/><line x1="18" y1="6" x2="6" y2="18"/></svg>';

  function makeItem(cls, svgStr, label) {
    var btn = document.createElement("button");
    btn.className = P + "mi " + P + cls;
    var icon = document.createElement("span");
    icon.className = P + "mi-icon";
    icon.innerHTML = svgStr;
    btn.appendChild(icon);
    var txt = document.createElement("span");
    txt.textContent = label;
    btn.appendChild(txt);
    return btn;
  }

  function buildWidget() {
    var el = document.createElement("div");
    el.className = P + "widget";

    /* ---- chip ---- */
    var chip = document.createElement("div");
    chip.className = P + "chip";

    var chipImg = document.createElement("img");
    chipImg.className = P + "chip-img";
    chipImg.src = IMG_OPTIN;
    chipImg.draggable = false;
    chip.appendChild(chipImg);

    var chipBtn = document.createElement("button");
    chipBtn.className = P + "chip-btn";
    chip.appendChild(chipBtn);

    /* top hit area (uses the visual element already in the image) */
    var chipTop = document.createElement("div");
    chipTop.className = P + "chip-top";
    chip.appendChild(chipTop);

    /* chip popup */
    var chipPopup = document.createElement("div");
    chipPopup.className = P + "popup";
    chipPopup.appendChild(makeItem("mi-min", SVG_MINIMIZE, "Minimize"));
    chipPopup.appendChild(makeItem("mi-terms", SVG_TERMS, "T&C"));
    chipPopup.appendChild(makeItem("mi-close", SVG_CLOSE, "Close"));
    chip.appendChild(chipPopup);

    el.appendChild(chip);

    /* ---- bar ---- */
    var bar = document.createElement("div");
    bar.className = P + "bar";

    var barImg = document.createElement("img");
    barImg.className = P + "bar-img";
    barImg.src = IMG_BAR;
    barImg.draggable = false;
    bar.appendChild(barImg);

    var barMenu = document.createElement("div");
    barMenu.className = P + "bar-menu";
    bar.appendChild(barMenu);

    var barPopup = document.createElement("div");
    barPopup.className = P + "popup";
    barPopup.appendChild(makeItem("mi-min", SVG_EXPAND, "Expand"));
    barPopup.appendChild(makeItem("mi-terms", SVG_TERMS, "T&C"));
    barPopup.appendChild(makeItem("mi-close", SVG_CLOSE, "Close"));
    bar.appendChild(barPopup);


    /* ---- T&C modal ---- */
    var overlay = document.createElement("div");
    overlay.className = P + "overlay";
    var modal = document.createElement("div");
    modal.className = P + "modal";
    var mHeader = document.createElement("div");
    mHeader.className = P + "modal-header";
    var mTitle = document.createElement("div");
    mTitle.className = P + "modal-title";
    mTitle.textContent = "Terms & Conditions";
    mHeader.appendChild(mTitle);
    var mX = document.createElement("button");
    mX.className = P + "modal-x";
    mX.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round"><line x1="6" y1="6" x2="18" y2="18"/><line x1="18" y1="6" x2="6" y2="18"/></svg>';
    mHeader.appendChild(mX);
    modal.appendChild(mHeader);
    var mBody = document.createElement("div");
    mBody.className = P + "modal-body";
    mBody.innerHTML = "<p><strong>Must Drop Jackpot</strong></p>" +
      "<p>The Must Drop Jackpot is a progressive jackpot that must be won before it reaches the displayed target amount. The jackpot amount increases with each qualifying bet placed by participating players.</p>" +
      "<p><strong>Eligibility</strong></p>" +
      "<p>To participate, players must opt in by clicking the OPT-IN button on the jackpot widget. Players can opt out at any time. Only bets placed while opted in will contribute to and qualify for the jackpot.</p>" +
      "<p><strong>Winning</strong></p>" +
      "<p>The jackpot is awarded randomly to one opted-in player. The probability of winning increases proportionally with the size of qualifying bets. The jackpot must drop before reaching its maximum threshold.</p>" +
      "<p><strong>General</strong></p>" +
      "<p>Standard wagering terms apply. The operator reserves the right to modify or cancel this promotion at any time. Minimum bet requirements may apply. Must be 18+ to participate. Please gamble responsibly.</p>";
    modal.appendChild(mBody);
    overlay.appendChild(modal);
    el.appendChild(overlay);

    el.appendChild(bar);
    return el;
  }

  function getOptIn() {
    try { return localStorage.getItem(STORAGE_KEY) === "1"; } catch (_) { return false; }
  }
  function setOptIn(val) {
    try { localStorage.setItem(STORAGE_KEY, val ? "1" : "0"); } catch (_) {}
  }

  /* Smart popup positioning: flip above/below based on available space */
  function positionPopup(popup, triggerEl) {
    /* reset so we can measure */
    popup.style.top = "auto";
    popup.style.bottom = "auto";
    popup.style.left = "auto";
    popup.style.right = "0";

    /* measure trigger in viewport */
    var triggerRect = triggerEl.getBoundingClientRect();
    var popupH = 160; /* approximate popup height (3 items * ~48px + padding) */

    var spaceAbove = triggerRect.top;
    var spaceBelow = window.innerHeight - triggerRect.bottom;

    /* find the trigger's offset within its positioned parent */
    var parent = triggerEl.offsetParent || triggerEl.parentNode;
    var parentRect = parent.getBoundingClientRect();
    var triggerTopInParent = triggerRect.top - parentRect.top;
    var triggerBottomInParent = triggerRect.bottom - parentRect.top;

    if (spaceAbove > spaceBelow && spaceAbove >= popupH) {
      /* show above trigger */
      popup.style.bottom = (parentRect.bottom - triggerRect.top + 6) + "px";
      popup.style.top = "auto";
    } else {
      /* show below trigger */
      popup.style.top = (triggerBottomInParent + 6) + "px";
      popup.style.bottom = "auto";
    }
  }

  function createController(cfg) {
    injectStyles();
    var widget = buildWidget();
    var optedIn = getOptIn();
    var minimized = false;
    var activePopup = null;
    var activeTrigger = null;

    var chipEl     = widget.querySelector("." + P + "chip");
    var chipImg    = widget.querySelector("." + P + "chip-img");
    var chipBtn    = widget.querySelector("." + P + "chip-btn");
    var chipTop    = widget.querySelector("." + P + "chip-top");
    var chipPopup  = chipEl.querySelector("." + P + "popup");

    var barEl      = widget.querySelector("." + P + "bar");
    var barMenu    = widget.querySelector("." + P + "bar-menu");
    var barPopup   = barEl.querySelector("." + P + "popup");

    var chipMinimize = chipPopup.children[0];
    var chipTerms    = chipPopup.children[1];
    var chipClose    = chipPopup.children[2];

    var barExpand  = barPopup.children[0];
    var barTerms   = barPopup.children[1];
    var barClose   = barPopup.children[2];

    var tcOverlay = widget.querySelector("." + P + "overlay");
    var tcCloseBtn = tcOverlay.querySelector("." + P + "modal-x");

    function openTerms() {
      tcOverlay.classList.add(P + "open");
    }
    function closeTerms() {
      tcOverlay.classList.remove(P + "open");
    }
    tcCloseBtn.addEventListener("click", function (e) {
      e.stopPropagation();
      closeTerms();
    });
    tcOverlay.addEventListener("click", function (e) {
      if (e.target === tcOverlay) closeTerms();
    });

    function renderOptState() {
      chipImg.src = optedIn ? IMG_OPTOUT : IMG_OPTIN;
    }

    function closeAllMenus() {
      chipPopup.classList.remove(P + "open");
      barPopup.classList.remove(P + "open");
      activePopup = null;
      activeTrigger = null;
    }

    function togglePopup(popup, trigger) {
      if (activePopup === popup) {
        closeAllMenus();
      } else {
        closeAllMenus();
        popup.classList.add(P + "open");
        positionPopup(popup, trigger);
        activePopup = popup;
        activeTrigger = trigger;
      }
    }

    function setMinimized(val) {
      minimized = val;
      chipEl.style.display = minimized ? "none" : "block";
      barEl.style.display  = minimized ? "block" : "none";
      closeAllMenus();
    }

    /* opt in/out */
    chipBtn.addEventListener("click", function (e) {
      e.stopPropagation();
      optedIn = !optedIn;
      setOptIn(optedIn);
      renderOptState();
      if (optedIn && typeof cfg.onOptIn === "function") cfg.onOptIn();
      if (!optedIn && typeof cfg.onOptOut === "function") cfg.onOptOut();
    });

    /* chip top area toggles menu */
    chipTop.addEventListener("click", function (e) {
      e.stopPropagation();
      togglePopup(chipPopup, chipTop);
    });

    chipMinimize.addEventListener("click", function (e) {
      e.stopPropagation();
      setMinimized(true);
    });
    chipTerms.addEventListener("click", function (e) {
      e.stopPropagation();
      closeAllMenus();
      openTerms(); if (typeof cfg.onTerms === "function") cfg.onTerms();
    });
    chipClose.addEventListener("click", function (e) {
      e.stopPropagation();
      closeAllMenus();
    });

    /* bar hamburger toggles menu */
    barMenu.addEventListener("click", function (e) {
      e.stopPropagation();
      togglePopup(barPopup, barMenu);
    });

    barExpand.addEventListener("click", function (e) {
      e.stopPropagation();
      setMinimized(false);
    });
    barTerms.addEventListener("click", function (e) {
      e.stopPropagation();
      closeAllMenus();
      openTerms(); if (typeof cfg.onTerms === "function") cfg.onTerms();
    });
    barClose.addEventListener("click", function (e) {
      e.stopPropagation();
      closeAllMenus();
    });

    /* close menus on outside click */
    document.addEventListener("click", function () {
      if (activePopup) closeAllMenus();
    });

    /* drag */
    var dragCleanup = [];
    function isMenuEl(target) {
      return target === barMenu || barMenu.contains(target) ||
             target === barPopup || barPopup.contains(target) ||
             target === chipTop || chipTop.contains(target) ||
             target === chipPopup || chipPopup.contains(target);
    }

    function setupDrag() {
      if (!cfg.draggable) return;
      var dragging = false, offsetX = 0, offsetY = 0;
      var widgetW = 0, widgetH = 0, isFixed = false;
      var startX = 0, startY = 0, didMove = false;

      function convertToLeftTop() {
        var r = widget.getBoundingClientRect();
        if (isFixed) {
          widget.style.left = r.left + "px"; widget.style.top = r.top + "px";
        } else {
          var c = widget.parentNode.getBoundingClientRect();
          widget.style.left = (r.left - c.left) + "px"; widget.style.top = (r.top - c.top) + "px";
        }
        widget.style.right = "auto"; widget.style.bottom = "auto"; widget.style.transform = "none";
        widget.classList.remove(P + "pos-" + cfg.position);
      }

      function onStart(cx, cy, e) {
        if (e && e.target === chipBtn) return;
        if (e && isMenuEl(e.target)) return;
        dragging = true; didMove = false; startX = cx; startY = cy;
        isFixed = widget.classList.contains(P + "fixed");
        var r = widget.getBoundingClientRect();
        widgetW = r.width; widgetH = r.height;
        convertToLeftTop();
        var r2 = widget.getBoundingClientRect();
        offsetX = cx - r2.left; offsetY = cy - r2.top;
        (minimized ? barEl : chipEl).classList.add(P + "dragging");
      }

      function onMove(cx, cy) {
        if (!dragging) return;
        if (!didMove && Math.abs(cx - startX) < 4 && Math.abs(cy - startY) < 4) return;
        didMove = true;
        var nl, nt;
        if (isFixed) {
          nl = Math.max(0, Math.min(cx - offsetX, window.innerWidth - widgetW));
          nt = Math.max(0, Math.min(cy - offsetY, window.innerHeight - widgetH));
        } else {
          var c = widget.parentNode.getBoundingClientRect();
          nl = Math.max(0, Math.min(cx - offsetX - c.left, c.width - widgetW));
          nt = Math.max(0, Math.min(cy - offsetY - c.top, c.height - widgetH));
        }
        widget.style.left = nl + "px"; widget.style.top = nt + "px";
        widget.style.right = "auto"; widget.style.bottom = "auto";
      }

      function onEnd() {
        if (!dragging) return; dragging = false;
        chipEl.classList.remove(P + "dragging");
        barEl.classList.remove(P + "dragging");
      }

      function onMD(e) {
        if (e.target === chipBtn || isMenuEl(e.target)) return;
        e.preventDefault(); onStart(e.clientX, e.clientY, e);
      }
      function onMM(e) { if (!dragging) return; e.preventDefault(); onMove(e.clientX, e.clientY); }

      widget.addEventListener("mousedown", onMD);
      document.addEventListener("mousemove", onMM);
      document.addEventListener("mouseup", onEnd);

      function onTS(e) {
        if (e.target === chipBtn || isMenuEl(e.target)) return;
        var t = e.touches[0]; onStart(t.clientX, t.clientY, e);
      }
      function onTM(e) { if (!dragging) return; e.preventDefault(); var t = e.touches[0]; onMove(t.clientX, t.clientY); }

      widget.addEventListener("touchstart", onTS, { passive: true });
      document.addEventListener("touchmove", onTM, { passive: false });
      document.addEventListener("touchend", onEnd);

      dragCleanup.push(function () {
        widget.removeEventListener("mousedown", onMD);
        document.removeEventListener("mousemove", onMM);
        document.removeEventListener("mouseup", onEnd);
        widget.removeEventListener("touchstart", onTS);
        document.removeEventListener("touchmove", onTM);
        document.removeEventListener("touchend", onEnd);
      });
    }

    function mount() {
      var container = null;
      if (cfg.containerId) {
        container = document.getElementById(cfg.containerId);
        if (container) {
          if (getComputedStyle(container).position === "static") container.style.position = "relative";
          widget.classList.add(P + "contained");
        }
      }
      if (!container) { container = document.body; widget.classList.add(P + "fixed"); }
      widget.classList.add(P + "pos-" + cfg.position);
      container.appendChild(widget);
      renderOptState();
      setupDrag();
    }

    return {
      mount: mount,
      destroy: function () {
        for (var i = 0; i < dragCleanup.length; i++) dragCleanup[i]();
        dragCleanup = [];
        if (widget.parentNode) widget.parentNode.removeChild(widget);
      },
      isOptedIn: function () { return optedIn; },
      minimize: function () { setMinimized(true); },
      expand: function () { setMinimized(false); }
    };
  }

  window.JackpotMustDropWidget = {
    init: function (userConfig) {
      var cfg = {};
      for (var k in DEFAULTS) {
        if (DEFAULTS.hasOwnProperty(k)) {
          cfg[k] = userConfig && userConfig.hasOwnProperty(k) ? userConfig[k] : DEFAULTS[k];
        }
      }
      var ctrl = createController(cfg);
      if (document.readyState === "complete" || document.readyState === "interactive") {
        ctrl.mount();
      } else {
        document.addEventListener("DOMContentLoaded", function () { ctrl.mount(); });
      }
      return ctrl;
    }
  };
})();
